# ci.sh <branch> [n] — die letzten n Läufe je Branch mit Jobs und Fehl-Schritt
b=$1; n=${2:-2}
curl -s "https://api.github.com/repos/MiguellD/AnazhRealm/actions/runs?branch=$b&per_page=$n" | node -e "let d='';process.stdin.on('data',c=>d+=c).on('end',async()=>{for(const r of JSON.parse(d).workflow_runs||[]){const j=await (await fetch('https://api.github.com/repos/MiguellD/AnazhRealm/actions/runs/'+r.id+'/jobs')).json();console.log('$b',r.id,r.head_sha.slice(0,8),r.event,r.status,r.conclusion,r.created_at);for(const b of j.jobs||[]){const f=(b.steps||[]).filter(s=>s.conclusion==='failure'||s.conclusion==='cancelled');const ip=(b.steps||[]).find(s=>s.status==='in_progress');console.log('  ',b.name,b.status,b.conclusion,f.map(s=>s.conclusion+' '+s.number+' '+s.name.slice(0,40)).join(' | '),ip?'läuft '+ip.number+' '+ip.name.slice(0,40):'')}}})"
